create table if not exists public.user_profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null check (role in ('admin','office_staff','supervisor','worker')), factory_id text, employee_id uuid references public.employees(id) on delete set null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint worker_requires_employee check (role <> 'worker' or employee_id is not null), constraint supervisor_requires_factory check (role <> 'supervisor' or factory_id is not null)); alter table public.employees add column if not exists auth_user_id uuid references auth.users(id) on delete set null; create unique index if not exists employees_auth_user_id_uidx on public.employees(auth_user_id) where auth_user_id is not null;